params.expression:
yaw => {
          const actual = window.__NEON__.snapshot().camera.yaw;
          return Math.abs(Math.atan2(Math.sin(actual - yaw), Math.cos(actual - yaw))) < .025;
        }

before => {
          const p = window.__NEON__.snapshot().city.sample.transit.passengerLocal;
          return p && Math.hypot(p.x - before.x, p.z - before.z) > .009;
        }

() => {
  const s = window.__NEON__.snapshot(),
    t = s.city.sample.transit;
  return {
    local: t.passengerLocal,
    vehicle: t.vehicles.find(v => v.id === t.ridingVehicleId),
    cameraYaw: s.camera?.yaw,
    sensitivity: s.settings.sensitivity,
    time: s.simulationTime,
    teleportRevision: s.teleportRevision,
    deck: t.passengerDeck
  };
}

